import{_ as e,o,c as a,a2 as s}from"./chunks/framework.dWYrTn1b.js";const p=JSON.parse('{"title":"Gazebo or MuJoCo","description":"The two targets, what they share, how they differ, and what each refuses.","frontmatter":{"title":"Gazebo or MuJoCo","description":"The two targets, what they share, how they differ, and what each refuses."},"headers":[],"relativePath":"guide/advanced/simulators.md","filePath":"guide/advanced/simulators.md"}'),r={name:"guide/advanced/simulators.md"};function i(d,t,h,n,l,c){return o(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="gazebo-or-mujoco" tabindex="-1">Gazebo or MuJoCo <a class="header-anchor" href="#gazebo-or-mujoco" aria-label="Permalink to &quot;Gazebo or MuJoCo&quot;">​</a></h1><p>Both targets emit the same robot description, controllers, Nav2 settings, map, task and runtime. They differ in the simulator underneath.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mobiledsl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ros-gz-nav2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mobiledsl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ros-mujoco-nav2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build_mujoco</span></span></code></pre></div><h2 id="what-each-runs" tabindex="-1">What each runs <a class="header-anchor" href="#what-each-runs" aria-label="Permalink to &quot;What each runs&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><code>ros-gz-nav2</code></th><th><code>ros-mujoco-nav2</code></th></tr></thead><tbody><tr><td>Simulator</td><td>Gazebo Harmonic</td><td>MuJoCo 3.3, run by the output&#39;s own node</td></tr><tr><td>The world</td><td><code>world/world.sdf</code> and <code>world/bridge.yaml</code></td><td><code>world/mujoco.json</code></td></tr><tr><td>Robot to controllers</td><td><code>gz_ros2_control</code></td><td><code>topic_based_ros2_control</code></td></tr><tr><td>Sensors</td><td>Gazebo&#39;s sensor plugins</td><td>Computed from the physics state: rays for lasers and range finders, offscreen rendering for cameras</td></tr><tr><td>A window</td><td><code>headless:=false</code></td><td>None</td></tr><tr><td>Test image</td><td><code>robotdsl/ros-gz-nav2:jazzy-harmonic</code></td><td><code>robotdsl/ros-mujoco-nav2:jazzy</code></td></tr></tbody></table><p>Both publish the same topics, including the robot&#39;s ground-truth pose on <code>/model/&lt;robot&gt;/pose</code>, so the same task runner judges both.</p><h2 id="what-each-refuses" tabindex="-1">What each refuses <a class="header-anchor" href="#what-each-refuses" aria-label="Permalink to &quot;What each refuses&quot;">​</a></h2><p>A target refuses what it cannot simulate, at compile time, instead of writing something that runs wrong.</p><table tabindex="0"><thead><tr><th>Construct</th><th><code>ros-gz-nav2</code></th><th><code>ros-mujoco-nav2</code></th></tr></thead><tbody><tr><td>A mecanum or omni base</td><td>Simulated</td><td>Refused: MuJoCo&#39;s contact friction is the same in every direction, so a wheel cannot slide freely along its rollers</td></tr><tr><td>A part without a collision box</td><td>Collides through its visual mesh</td><td>Refused: MuJoCo cannot read the Collada mesh</td></tr><tr><td>A movable entity (<code>is_static = false</code>)</td><td>Refused</td><td>Refused</td></tr><tr><td>A base environment other than <code>&quot;empty&quot;</code></td><td>Refused</td><td>Refused</td></tr><tr><td>A scene entity given by <code>ref</code></td><td>Refused</td><td>Refused</td></tr></tbody></table><h2 id="where-they-differ-in-behaviour" tabindex="-1">Where they differ in behaviour <a class="header-anchor" href="#where-they-differ-in-behaviour" aria-label="Permalink to &quot;Where they differ in behaviour&quot;">​</a></h2><ul><li><strong>Skid-steer turns.</strong> In MuJoCo a skid-steer base turns in place at about a third of the commanded rate, while its wheel odometry reports the full turn.</li><li><strong>Contacts.</strong> Gazebo gives each kind of wheel its own friction model, anisotropic where the wheel slides one way. MuJoCo gives a rolling wheel a grip of 1 and a caster or skid 0.01, in every direction.</li><li><strong>The drive.</strong> MuJoCo drives each wheel through a velocity actuator whose gain the target chooses, since the library does not state the motors&#39; response.</li></ul><p>Each of these is declared in <code>compile.json</code>.</p><h2 id="which-to-use" tabindex="-1">Which to use <a class="header-anchor" href="#which-to-use" aria-label="Permalink to &quot;Which to use&quot;">​</a></h2><p>Use <code>ros-gz-nav2</code> for any base, and for parts that declare no collision box. Use <code>ros-mujoco-nav2</code> for a base on standard wheels when you want a second simulator&#39;s opinion of the same program: a run that passes in one and fails in the other points at something the program leaves to a simulator&#39;s defaults.</p><p><a href="./../../reference/output.html">The output contract</a> specifies both targets&#39; files in full.</p>`,15)])])}const m=e(r,[["render",i]]);export{p as __pageData,m as default};
